export function resolveMoogDialScaleProfile(spec,{size='medium'}={}){
  if(String(size)==='small')return'none'
  const id=String(spec?.id||'').toLowerCase(),min=Number(spec?.minimum),max=Number(spec?.maximum),span=max-min
  if(!Number.isFinite(min)||!Number.isFinite(max)||!(span>0))return'none'
  const symmetricBipolar=min<0&&max>0&&Math.abs(min+max)<=Math.max(1e-9,span*.01)
  if(symmetricBipolar)return'bipolar'
  if(/(tempo-bpm|clock-rate|rate-hz|lfo-rate|rate-bpm)/.test(id))return'rate'
  if(String(spec?.format||'').toLowerCase()==='hz'||/(frequency|freq|cutoff|carrier-hz|tune)/.test(id))return'frequency'
  if(String(spec?.format||'').toLowerCase()==='ms'||/(attack|decay|glide|rise|fall|slew|time)/.test(id))return'time'
  if(/(^|[-_])(blend|mix|balance|pan)([-_]|$)|pulse-width|pwm-width/.test(id))return'center'
  if(/(amount|amt|depth|resonance|drive|fold|fm|feedback|damping|swing-amount)/.test(id))return'amount'
  return'none'
}

function normaliseHexColor(value,fallback='#e7dcc5'){
  const text=String(value||'').trim();return /^#[0-9a-f]{6}$/i.test(text)?text.toLowerCase():fallback
}
