  shell.style.setProperty('--shell-hi',palette.hi);shell.style.setProperty('--shell-mid',palette.mid);shell.style.setProperty('--shell-low',palette.low);shell.style.setProperty('--shell-edge',palette.edge);shell.style.setProperty('--shell-border',palette.border);shell.style.setProperty('--shell-foot',palette.foot);shell.dataset.chassisColor=base;return base
