export function addMoogHardware(shell){
  const hardware=el('div','moog-hardware')
  for(let index=0;index<4;index+=1)hardware.append(el('i','moog-screw'))
  shell.append(hardware)
  return hardware
}

export function appendGroupedPresetOptions(select,presets=[]){
  const groups=new Map()
  for(const row of presets){const category=String(row.category||'Other');if(!groups.has(category))groups.set(category,[]);groups.get(category).push(row)}
  for(const [category,rows] of groups){const group=document.createElement('optgroup');group.label=category;for(const row of rows){const option=document.createElement('option');option.value=row.id;option.textContent=String(row.label||row.id);option.dataset.presetCategory=category;option.dataset.presetTags=JSON.stringify(Array.isArray(row.tags)?row.tags.map(String):[]);option.dataset.presetEngineId=String(row.engineId||'');group.append(option)}select.append(group)}
  select.dataset.presetGroupCount=String(groups.size)
  return groups.size
}

